package witchinggadgets;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.effect.MobEffectInstance;
import net.minecraft.world.entity.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.neoforged.neoforge.gametest.*;
import thaumcraft.aspect.Aspect;

@GameTestHolder(WitchingGadgets.ID) @PrefixGameTestTemplate(false)
public final class Port4Tests {
    @GameTest(template="test/platform") public static void pumpLineOfSightDoesNotCreateNullEntityCollisionContext(GameTestHelper h){var pump=PortGameTests.place(h,"essentia_pump");var l=h.getLevel();var front=pump.getBlockPos().north();l.setBlockAndUpdate(front,Content.block("terrestrial_reformer").defaultBlockState());((MachineEntity)l.getBlockEntity(front)).essentia=Aspect.FIRE;var mirror=pump.getBlockPos().south(2);l.setBlockAndUpdate(mirror.south(),Blocks.STONE.defaultBlockState());l.setBlockAndUpdate(mirror,thaumcraft.registry.ModBlocks.ESSENTIA_MIRROR.get().defaultBlockState().setValue(thaumcraft.device.MirrorBlock.FACING,Direction.NORTH));pump.age=5;pump.pump(l);h.assertValueEqual(pump.amount,0,"unlinked mirror supplied essentia");h.succeed();}
    @GameTest(template="test/platform") public static void furnaceRejectsWrongItemWithOneOriginalFizz(GameTestHelper h){var m=IntegrationGameTests.form(h);var at=m.getBlockPos().above(2);var state=h.getLevel().getBlockState(at);var item=new net.minecraft.world.entity.item.ItemEntity(h.getLevel(),at.getX()+.5,at.getY()+.5,at.getZ()+.5,new ItemStack(Items.DIRT));var heard=EffectsGameTests.hear(h,()->((FurnaceBlock)state.getBlock()).entityInside(state,h.getLevel(),at,item));h.assertTrue(!item.isAlive(),"wrong furnace input no longer vaporizes like the release");h.assertValueEqual(EffectsGameTests.count(heard,net.minecraft.sounds.SoundEvents.FIRE_EXTINGUISH),1L,"rejected input hiss missing");h.succeed();}
    @GameTest(template="test/platform") public static void matureRoseOutlineIsCachedEvenWithFourWalls(GameTestHelper h){var m=PortGameTests.place(h,"rose_vines");var p=m.getBlockPos();for(var d:Direction.values())if(d!=Direction.UP)h.getLevel().setBlockAndUpdate(p.relative(d),Blocks.STONE.defaultBlockState());m.progress=5;long start=System.nanoTime();var shape=RoseGeometry.shape(h.getLevel(),p);for(int i=0;i<2000;i++)h.assertTrue(shape==RoseGeometry.shape(h.getLevel(),p),"outline mesh rebuilt on every mouse-over");h.assertTrue((System.nanoTime()-start)<3_000_000_000L,"mature-vine selection stalls server");m.progress=0;h.assertTrue(shape!=RoseGeometry.shape(h.getLevel(),p),"growth uses stale outline");h.succeed();}
    @GameTest(template="test/platform") public static void allSevenFocusRecipesKeepOriginalIron(GameTestHelper h){int recipes=0;for(var entry:PortData.read("recipes")){var o=entry.getAsJsonObject();if(!o.has("output")||!PortData.str(o.getAsJsonObject("output"),"id").startsWith("witchinggadgets:focus_"))continue;recipes++;var ingredients=new ArrayList<com.google.gson.JsonObject>();if(o.has("symbols"))o.getAsJsonObject("symbols").entrySet().forEach(e->ingredients.add(e.getValue().getAsJsonObject()));else o.getAsJsonArray("ingredients").forEach(e->ingredients.add(e.getAsJsonObject()));h.assertTrue(ingredients.stream().anyMatch(i->PortData.str(i,"id").equals("minecraft:iron_ingot")),"focus lacks original iron");h.assertTrue(ingredients.stream().noneMatch(i->PortData.str(i,"id").equals("minecraft:slime_ball")),"cosmetic focus redesign changed the recipe to slime");}h.assertValueEqual(recipes,7,"focus recipe missing");h.succeed();}
    @GameTest(template="test/platform") public static void changingFurnaceInputCannotReuseProgress(GameTestHelper h){var m=IntegrationGameTests.form(h);m.items.setStackInSlot(0,new ItemStack(Content.tc("native_iron_cluster")));for(int i=0;i<430;i++)m.blast(h.getLevel());m.items.setStackInSlot(0,new ItemStack(Content.tc("native_gold_cluster")));m.blast(h.getLevel());h.assertValueEqual(m.progress,1,"new metal inherited near-complete smelt");h.assertTrue(m.items.getStackInSlot(2).isEmpty(),"instant output from swapped input");h.succeed();}
    @GameTest(template="test/platform") public static void legacyOutputIsReleasedAndCannotBlockSmelting(GameTestHelper h){var m=IntegrationGameTests.form(h);m.items.setStackInSlot(0,new ItemStack(Content.tc("native_iron_cluster"),8));m.items.setStackInSlot(2,new ItemStack(Items.IRON_INGOT,63));for(int i=0;i<1000;i++)m.blast(h.getLevel());h.assertValueEqual(m.items.getStackInSlot(0).getCount(),6,"old buffered output blocks smelting");h.assertValueEqual(Port5Tests.dropped(h,m,Items.IRON_INGOT),69,"stored or freshly smelted ingots lost/duplicated");h.succeed();}
    @GameTest(template="test/platform") public static void droppedClusterAboveLavaEntersRealFurnace(GameTestHelper h){var m=IntegrationGameTests.form(h);var pos=m.getBlockPos();var item=new net.minecraft.world.entity.item.ItemEntity(h.getLevel(),pos.getX()+.5,pos.getY()+3.05,pos.getZ()+.5,new ItemStack(Content.tc("native_iron_cluster"),3));h.getLevel().addFreshEntity(item);m.age=5;m.blast(h.getLevel());h.assertTrue(!item.isAlive()&&m.items.getStackInSlot(0).getCount()==3,"top surface misses dropped input");h.assertTrue(h.getLevel().getBlockState(pos.above(2)).getCollisionShape(h.getLevel(),pos.above(2)).isEmpty(),"invisible solid cube blocks the lava opening");h.succeed();}
    @GameTest(template="test/platform") public static void furnaceProgressSurvivesSavingAndKeepsRecipeIdentity(GameTestHelper h){var m=IntegrationGameTests.form(h);m.items.setStackInSlot(0,new ItemStack(Content.tc("native_iron_cluster")));for(int i=0;i<120;i++)m.blast(h.getLevel());var saved=m.saveWithFullMetadata(h.getLevel().registryAccess());var copy=new MachineEntity(m.getBlockPos(),m.getBlockState());copy.setLevel(h.getLevel());copy.loadWithComponents(saved,h.getLevel().registryAccess());copy.blast(h.getLevel());h.assertValueEqual(copy.progress,121,"loading resets or duplicates smelting progress");h.succeed();}
    @GameTest(template="test/platform") public static void furnaceBellowsMustFaceTheFurnace(GameTestHelper h){var m=IntegrationGameTests.form(h);var pos=m.getBlockPos().east(2);var block=thaumcraft.registry.ModBlocks.ARCANE_BELLOWS.get();h.getLevel().setBlockAndUpdate(pos,block.defaultBlockState().setValue(thaumcraft.alchemy.BellowsBlock.FACING,Direction.EAST));h.assertValueEqual(Multiblock.bellows(m),0,"backwards bellows counted");h.getLevel().setBlockAndUpdate(pos,block.defaultBlockState().setValue(thaumcraft.alchemy.BellowsBlock.FACING,Direction.WEST));h.assertValueEqual(Multiblock.bellows(m),1,"inward bellows ignored");m.items.setStackInSlot(0,new ItemStack(Content.tc("native_iron_cluster")));h.assertValueEqual(m.blastTime(),400,"one bellows must save 40 ticks");h.succeed();}
    @GameTest(template="test/platform") public static void cinderCoatMultipliesFireDamageAndEndsCleanly(GameTestHelper h){var cow=h.spawn(EntityType.COW,new BlockPos(2,2,2));float start=cow.getHealth();cow.addEffect(new MobEffectInstance(StatusEffects.CINDER,80,1));cow.hurt(cow.damageSources().onFire(),1);h.assertValueEqual(start-cow.getHealth(),3F,"cinder is weakness instead of triple fire damage");cow.removeEffect(StatusEffects.CINDER);cow.invulnerableTime=0;start=cow.getHealth();cow.hurt(cow.damageSources().onFire(),1);h.assertValueEqual(start-cow.getHealth(),1F,"expired cinder still amplifies fire");h.succeed();}
    @GameTest(template="test/platform") public static void dissolveDamagesUndeadUsingThaumcraftDamage(GameTestHelper h){var mob=h.spawn(EntityType.ZOMBIE,new BlockPos(2,2,2));float start=mob.getHealth();StatusEffects.DISSOLVE.get().applyEffectTick(mob,2);h.assertTrue(mob.getHealth()<start,"dissolve still uses poison immunity");h.assertTrue(StatusEffects.DISSOLVE.get().shouldApplyEffectTickThisTick(70,2)&&!StatusEffects.DISSOLVE.get().shouldApplyEffectTickThisTick(69,2),"dissolve lost original 40 >> amplifier cadence");h.succeed();}
    @GameTest(template="test/platform") public static void earthGemUsesTemporaryKnockbackStatus(GameTestHelper h){var p=h.makeMockPlayer(net.minecraft.world.level.GameType.SURVIVAL);GemItem.effect(p,Aspect.EARTH,0,0);h.assertTrue(p.hasEffect(StatusEffects.KNOCKBACK),"earth gem has no visible effect");h.assertValueEqual(p.getEffect(StatusEffects.KNOCKBACK).getDuration(),100,"earth gem duration changed");p.removeEffect(StatusEffects.KNOCKBACK);h.assertValueEqual(p.getAttributeValue(net.minecraft.world.entity.ai.attributes.Attributes.KNOCKBACK_RESISTANCE),0D,"knockback modifier survives effect expiry");h.succeed();}
}
